<?php require '../database.php';if(!empty($_SESSION['admin_id'])){header("Location: dashboard.php");exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$s=$conn->prepare("SELECT id,password FROM admins WHERE username=?");$s->bind_param("s",$u);$s->execute();$a=$s->get_result()->fetch_assoc();if($a&&password_verify($p,$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$u;header("Location: dashboard.php");exit;}else $err="Invalid admin credentials.";}?><!doctype html><html><head><title>Admin Login</title><link rel="stylesheet" href="../style.css"></head><body><main class="form"><h2>Admin Login</h2><?php if($err)echo '<p class="error">'.e($err).'</p>';?><form method="post"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button>Login</button></form><p class="muted">First run default: admin / admin123. Change this password before deployment.</p><a href="../index.php">Home</a></main></body></html>